/**
 * Beta-Bernoulli belief updating engine.
 *
 * Models confidence in a finding as a Beta(alpha, beta) posterior over an
 * unknown success probability. Observing a success/failure is a conjugate
 * update: alpha += 1 (success) or beta += 1 (failure). This module is pure
 * and deterministic — no randomness, no wall-clock reads — so it can be
 * property tested exhaustively.
 */
export type BetaParams = {
  alpha: number;
  beta: number;
};

export function createBetaPrior(alpha = 1, beta = 1): BetaParams {
  if (alpha <= 0 || beta <= 0) {
    throw new Error("Beta prior parameters must be strictly positive");
  }
  return { alpha, beta };
}

/** Conjugate update after observing a single Bernoulli outcome. */
export function betaUpdate(params: BetaParams, outcome: 0 | 1): BetaParams {
  return outcome === 1
    ? { alpha: params.alpha + 1, beta: params.beta }
    : { alpha: params.alpha, beta: params.beta + 1 };
}

/** Batch update — order-independent by construction (addition is commutative). */
export function betaUpdateBatch(params: BetaParams, outcomes: readonly (0 | 1)[]): BetaParams {
  return outcomes.reduce((acc, o) => betaUpdate(acc, o), params);
}

export function betaMean(params: BetaParams): number {
  return params.alpha / (params.alpha + params.beta);
}

export function betaVariance(params: BetaParams): number {
  const { alpha, beta } = params;
  const sum = alpha + beta;
  return (alpha * beta) / (sum * sum * (sum + 1));
}

/**
 * Approximate central credible interval using the normal approximation to
 * the Beta distribution. Adequate for alpha+beta large enough (>= ~10); for
 * small sample sizes the interval is clamped to [0, 1].
 */
export function betaCredibleInterval(
  params: BetaParams,
  z = 1.96,
): { lower: number; upper: number } {
  const mean = betaMean(params);
  const sd = Math.sqrt(betaVariance(params));
  return {
    lower: Math.max(0, mean - z * sd),
    upper: Math.min(1, mean + z * sd),
  };
}

src/lib/domain/causal.ts.source:
/**
 * Minimal causal estimators used to judge whether an automation/decision
 * actually moved an outcome metric, vs. naive correlation.
 *
 * - `estimateDifferenceInMeans`: naive estimator, biased under confounding.
 * - `estimateIPW`: inverse-propensity-weighted estimator — unbiased for the
 *   average treatment effect (ATE) when propensities are correctly specified,
 *   even under confounding. Ground-truth recovery is property-tested in
 *   `causal.test.ts` against synthetic data generated via the seeded PRNG.
 */
export type Unit = {
  treated: boolean;
  outcome: number;
  /** Known/estimated probability of being treated, given covariates (propensity score). */
  propensity: number;
};

export function estimateDifferenceInMeans(units: readonly Unit[]): number {
  const treated = units.filter((u) => u.treated);
  const control = units.filter((u) => !u.treated);
  if (treated.length === 0 || control.length === 0) {
    throw new Error("Need at least one treated and one control unit");
  }
  const mean = (xs: readonly Unit[]) => xs.reduce((a, u) => a + u.outcome, 0) / xs.length;
  return mean(treated) - mean(control);
}

/**
 * Inverse propensity weighting (Horvitz-Thompson) estimator of the Average
 * Treatment Effect:
 *   ATE = (1/n) * sum_i [ T_i*Y_i/e_i - (1-T_i)*Y_i/(1-e_i) ]
 */
export function estimateIPW(units: readonly Unit[]): number {
  if (units.length === 0) throw new Error("Need at least one unit");
  let sum = 0;
  for (const u of units) {
    if (u.propensity <= 0 || u.propensity >= 1) {
      throw new Error("Propensity scores must be strictly between 0 and 1 (positivity)");
    }
    sum += u.treated
      ? u.outcome / u.propensity
      : -u.outcome / (1 - u.propensity);
  }
  return sum / units.length;
}

src/lib/domain/clock.ts.source:
/**
 * Clock injection for time-dependent domain code. Domain code MUST accept a
 * `Clock` rather than calling `Date.now()`/`new Date()` directly, so tests
 * can freeze time deterministically. Enforced by
 * `src/lib/domain/convention.test.ts`.
 */
export type Clock = {
  now(): Date;
};

export const systemClock: Clock = {
  now: () => new Date(),
};

export function createFixedClock(isoTimestamp: string): Clock {
  const fixed = new Date(isoTimestamp);
  return { now: () => new Date(fixed.getTime()) };
}

/** A clock that advances by a fixed step every time `now()` is read — useful for testing ordering. */
export function createTickingClock(startIso: string, stepMs: number): Clock {
  let current = new Date(startIso).getTime();
  return {
    now: () => {
      const d = new Date(current);
      current += stepMs;
      return d;
    },
  };
}

